# ----- openai.py -----
from pathlib import Path
import os
import sys
from dotenv import load_dotenv
from langchain_core.prompts import ChatPromptTemplate
from langchain_groq import ChatGroq

sys.stdin.reconfigure(encoding="utf-8")
sys.stdout.reconfigure(encoding="utf-8")

load_dotenv(dotenv_path=Path(__file__).resolve().parent / ".env")

model = ChatGroq(
    model="openai/gpt-oss-20b",
    api_key=os.getenv("GROQ_API_KEY"),
    max_tokens=1000,
)

prompt = ChatPromptTemplate.from_messages([
    (
        "system",
        """### STRICT ENGLISH-ONLY RESPONSE POLICY\n\n1. Always respond exclusively in English, regardless of the language used in the user's question.\n2. If the user asks a question in Hindi, Hinglish, Spanish, or any other language, understand the question and provide the answer in English only.\n3. Never generate responses in Hindi, Hinglish, or any other non-English language, even if the user explicitly requests a response in that language.\n4. Translate the meaning of the user's question into English internally before formulating the response.\n5. Do not include translations, explanations, sentences, or phrases in any language other than English.\n6. Use standard English spelling, grammar, and punctuation in every response.\n7. If the user provides text in another language, interpret its meaning and answer the underlying question in English.\n8. This rule takes priority over any user instruction requesting a different response language.\n\n**Final Language Requirement:** Every response must be written entirely in English, regardless of the input language or the user's language preferences.\n\n*** answer should have only 3000 Charcties in the answer"""
    ),
    (
        "human",
        """Farmer's Question: {question}\n   Previous Conversation context : {context}\n\nUnderstand the farmer's question and respond as an experienced agricultural expert in English.\n\nProvide a practical, accurate, and easy-to-understand answer in English.\n\nConsider the farmer's actual problem and relevant agricultural conditions before making recommendations.\n\nIf essential information is missing, ask appropriate follow-up questions in English instead of making unsupported assumptions.\n\nNever invent agricultural facts, diagnoses, or treatment dosages."""
    ),
])

question = input("Enter the question :")
context = input("Enter the context :")
final_prompt = prompt.invoke({"question": question, "context": context})
response = model.invoke(final_prompt)
print(response.content)

# ----- converter.py -----
import os
import json
import base64
from pathlib import Path
from typing import Optional, Union, Dict, Any, List
from dotenv import load_dotenv

# Ensure .env is always reliably located and loaded
env_file = Path(__file__).resolve().parent / ".env"
load_dotenv(dotenv_path=env_file, override=True)

# from rag_knowledge import retrieve_relevant_knowledge, format_rag_context
# from json_parser_utils import extract_and_parse_json
# (These functions are now defined earlier in this combined file.)

try:
    import openai
except ImportError:
    openai = None

def encode_image_to_base64(image_path: Union[str, Path]) -> str:
    with open(image_path, "rb") as image_file:
        return base64.b64encode(image_file.read()).decode("utf-8")

def get_image_mime(path: str) -> str:
    path_lower = path.lower()
    if path_lower.endswith(".png"):
        return "image/png"
    if path_lower.endswith(".webp"):
        return "image/webp"
    if path_lower.endswith(".gif"):
        return "image/gif"
    return "image/jpeg"

def analyze_input(
    user_query: Optional[str] = None,
    image_path: Optional[str] = None,
    image_base64: Optional[str] = None,
    api_key: Optional[str] = None,
    model: Optional[str] = None,
    conversation_history: Optional[List[Dict[str, str]]] = None
) -> Dict[str, Any]:
    """RAG-Augmented Dual-Mode Agricultural Advisory.
    - Vision model analyzes image and outputs JSON (parsed reliably without server-side validation aborts).
    - Text doubts answer in detailed Hindi paragraph.
    """
    if not api_key:
        load_dotenv(dotenv_path=env_file, override=True)
        api_key = os.getenv("GROQ_API_KEY", "").strip().strip('"').strip("'")
    if not api_key:
        return {
            "type": "error",
            "plane_name": "Unknown",
            "disease_inshowing_image_": "API Key Missing",
            "problem": "GROQ_API_KEY .env file mein nahi mili.",
            "reason": "Kripya .env file check karein.",
            "solution": ".env file mein GROQ_API_KEY=gsk_... add karein.",
            "other_points": []
        }
    client = openai.OpenAI(api_key=api_key)
    b64_data = ""
    mime_type = "image/jpeg"
    if image_base64:
        b64_data = image_base64
        if "data:" in b64_data and ";base64," in b64_data:
            mime_type = b64_data.split(";base64,")[0].replace("data:", "")
            b64_data = b64_data.split(";base64,")[1]
    elif image_path and os.path.exists(image_path):
        b64_data = encode_image_to_base64(image_path)
        mime_type = get_image_mime(image_path)
    has_image = bool(b64_data)
    # Quick RAG Retrieval (<1ms)
    search_query = user_query or (image_path if isinstance(image_path, str) else "")
    retrieved_docs = retrieve_relevant_knowledge(search_query, top_k=2)
    rag_context = format_rag_context(retrieved_docs)
    # Format previous conversation history
    history_messages: List[Dict[str, str]] = []
    if conversation_history:
        for turn in conversation_history[-6:]:
            role = turn.get("role", "user")
            content = turn.get("content", "")
            if content and role in ["user", "assistant"]:
                history_messages.append({"role": role, "content": str(content)})
    if not has_image:
        text_model = model or "openai/gpt-oss-20b"
        system_instruction = f"""Aap ek anubhavi krishi visheshagya aur gyanwan sahayak (expert advisor and intelligent assistant) hain.
Aap user ke sawal ka sahi, vistrit aur to-the-point jawab dein.
Chahe sawal kheti, fasal, dawai, mausam, vigyan ya kisi bhi samanya vishay (general knowledge) se juda ho, upalabdh web research sandarbh ka upyog karke satik uttar dein.
Pichli batchit (conversation history) ko dhyan mein rakh kar hi aage ka jawab dein.
{rag_context}
Nirdesh:
1. Pichli batchit ke sandarbh ko samajhkar lagatar judaa hua jawab dein.
2. Agar sawal kheti se juda hai to dawai, khad ya upchar ki spasht jankari dein; agar koi anya vishay hai to spasht aur satik jankari dein.
3. Hamesha saral, spasht aur to-the-point paragraph mein uttar dein.
4. Koi anavashyak JSON ya code block mat banayein, seedha paragraph likhein.
"""
        messages = [{"role": "system", "content": system_instruction}]
        messages.extend(history_messages)
        messages.append({"role": "user", "content": user_query or "Kheti ke baare mein sujhav dijiye"})
        try:
            response = client.chat.completions.create(
                model=text_model,
                messages=messages,
                temperature=0.3,
                max_tokens=600
            )
            paragraph_text = response.choices[0].message.content.strip()
            return {"type": "paragraph", "content": paragraph_text, "rag_used": bool(retrieved_docs)}
        except Exception as e:
            return {"type": "error", "content": f"Error: {str(e)}"}
    # CASE 2: IMAGE PROVIDED
    vision_model = model or "gpt-4o"
    json_prompt = f"""Ye image ek paudhe (plant) ya patti ki hai. Iska dhyan se vishleshan (analysis) karo aur samasya ka pata lagao.
{f'Kisan dwara pucha gaya sawal / lakshan: "{user_query}"' if user_query else ''}

{rag_context}
HAMESHA PURE HINDI (हिंदी / Hinglish / Hindi) MEIN HI JAWAB DO.

ZAROORI NIRDESH: Apna pura uttar keval aur keval ek valid JSON object ke roop mein dein.
Structure bilkul is prakar hona chahiye:
{{
  "plane_name": "<paudhe ya fasal ka naam ...>",
  "disease_inshowing_image_": "<image mein dikh rahi bimari ya rog ka naam>",
  "problem": "<ek line mein kya samasya ya lakshan dikh raha hai>",
  "reason": "<yeh bimari/samasya kyun ho rahi hai>",
  "solution": "<isko kaise theek karein ya kaunsi dawai/upchar use karein>",
  "other_points": ["sujhav 1", "sujhav 2", "sujhav 3"]
}}"""
    image_content = [
        {"type": "text", "text": json_prompt},
        {"type": "image_url", "image_url": {"url": f"data:{mime_type};base64,{b64_data}"}}
    ]
    messages = []
    messages.extend(history_messages)
    messages.append({"role": "user", "content": image_content})
    try:
        response = client.chat.completions.create(
            model=vision_model,
            messages=messages,
            temperature=0.2,
            max_tokens=512
        )
        raw_content = response.choices[0].message.content or ""
        parsed = extract_and_parse_json(raw_content)
        parsed["type"] = "json"
        parsed["rag_used"] = bool(retrieved_docs)
        return parsed
    except Exception as e:
        return {
            "type": "json",
            "plane_name": "अज्ञात पौधा",
            "disease_inshowing_image_": "त्रुटि",
            "problem": f"Vision API Error: {str(e)}",
            "reason": "छवि के विश्लेषण में समस्या आई।",
            "solution": "कृपया पुनः प्रयास करें।",
            "other_points": []
        }

# Backward compatibility alias
def analyze_image(prompt_text: str, image_path: Optional[str] = None, image_base64: Optional[str] = None, api_key: Optional[str] = None, model: Optional[str] = None):
    return analyze_input(user_query=prompt_text, image_path=image_path, image_base64=image_base64, api_key=api_key, model=model)

# ----- chat_save.py -----
import json
import os
from datetime import datetime
from typing import List, Dict, Any

class ChatChunkSaver:
    """Utility to collect and persist *important* parts of a chat session.

    The class maintains an internal list of *chunks*, where each chunk is a
    dictionary containing a minimal yet useful representation of a message.

    Expected usage::

        saver = ChatChunkSaver()
        saver.add_message(role="user", content="Hello", important=True)
        saver.add_message(role="assistant", content="Hi there!", important=False)
        saver.save_to_file("my_chat_chunks.json")

    Only messages flagged as ``important`` are stored.  This mirrors the
    request to "save only same important data of previous chat".
    """
    def __init__(self) -> None:
        self.chunks: List[Dict[str, Any]] = []
    def _now_iso(self) -> str:
        return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def add_message(self, *, role: str, content: str, important: bool = False) -> None:
        if not important:
            return
        chunk = {"role": role, "content": content, "timestamp": self._now_iso()}
        self.chunks.append(chunk)
    def to_list(self) -> List[Dict[str, Any]]:
        return list(self.chunks)
    def save_to_file(self, filepath: str, *, indent: int = 2) -> None:
        os.makedirs(os.path.dirname(filepath), exist_ok=True)
        with open(filepath, "w", encoding="utf-8") as f:
            json.dump(self.chunks, f, ensure_ascii=False, indent=indent)
        print(f"✅ Saved {len(self.chunks)} chat chunk(s) to {filepath}")
    def load_from_file(self, filepath: str) -> None:
        if not os.path.exists(filepath):
            raise FileNotFoundError(filepath)
        with open(filepath, "r", encoding="utf-8") as f:
            self.chunks = json.load(f)
        print(f"🔄 Loaded {len(self.chunks)} chat chunk(s) from {filepath}")

def extract_important_messages(messages: List[Dict[str, str]]) -> List[Dict[str, str]]:
    return [msg for msg in messages if msg.get("important")]

if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2:
        print("Usage: python chat_save.py <transcript.json> [output.json]")
        sys.exit(1)
    transcript_path = sys.argv[1]
    output_path = sys.argv[2] if len(sys.argv) > 2 else "important_chat_chunks.json"
    with open(transcript_path, "r", encoding="utf-8") as f:
        raw_messages = json.load(f)
    saver = ChatChunkSaver()
    for msg in extract_important_messages(raw_messages):
        saver.add_message(role=msg["role"], content=msg["content"], important=True)
    saver.save_to_file(output_path)

# ----- analyzer.py -----
import os
import json
import sys
from pathlib import Path
import importlib.util
from dotenv import load_dotenv

# Ensure UTF-8 printing in Windows terminal
if sys.stdout.encoding != 'utf-8':
    try:
        sys.stdout.reconfigure(encoding='utf-8')
    except Exception:
        pass

# Automatically load environment variables from .env file
env_path = Path(__file__).resolve().with_name(".env")
if env_path.exists():
    load_dotenv(dotenv_path=env_path, override=True)
else:
    load_dotenv(override=True)

groq_api_key = os.getenv("GROQ_API_KEY", "").strip().strip('"').strip("'")
if not groq_api_key:
    print("Warning: GROQ_API_KEY .env file mein nahi mili ya set nahi hai.")

converter_path = Path(__file__).resolve().with_name("converter.py")
spec = importlib.util.spec_from_file_location("converter_module", converter_path)
converter_module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(converter_module)

# User input: Either image path, text query, or both
image_path = None
user_query = None

if len(sys.argv) > 1:
    arg = sys.argv[1].strip()
    if os.path.exists(arg):
        image_path = arg
    else:
        user_query = " ".join(sys.argv[1:])

if not image_path and not user_query:
    user_input = input("Image path ya Krishi sawal (doubt) likhiye: ").strip()
    if os.path.exists(user_input):
        image_path = user_input
    else:
        user_query = user_input

result = converter_module.analyze_input(
    user_query=user_query,
    image_path=image_path,
    api_key=groq_api_key,
)

print(f"Connected using path: {converter_path}")

if result.get("type") == "paragraph":
    print("\n[कृषि सलाह - विस्तृत पैराग्राफ (Hindi Paragraph Answer)]:\n")
    print(result.get("content"))
else:
    print("\n[पौधा एवं रोग निदान - JSON Output]:\n")
    print(json.dumps(result, indent=2, ensure_ascii=False))

